-- Ripple Control audit schema (generated by integrations/snowflake/load.py --print-ddl)
CREATE SCHEMA IF NOT EXISTS RIPPLE_AUDIT;
USE SCHEMA RIPPLE_AUDIT;

CREATE TABLE IF NOT EXISTS AUDIT_EVENTS (
  run_id VARCHAR,
  event_id VARCHAR,
  received_at TIMESTAMP_NTZ,
  source VARCHAR,
  incident_types VARCHAR,
  incident_count INTEGER,
  is_compound BOOLEAN,
  outcome VARCHAR,
  writes_confirmed INTEGER,
  writes_rejected INTEGER,
  writes_unknown INTEGER,
  reads INTEGER,
  blocked_by_validation INTEGER,
  escalated BOOLEAN,
  action_kinds VARCHAR,
  extractor VARCHAR,
  duration_ms FLOAT,
  summary VARCHAR,
  snapshot_id VARCHAR,
  loaded_at TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  CONSTRAINT pk_audit_events PRIMARY KEY (run_id, event_id)
);
CREATE TRANSIENT TABLE IF NOT EXISTS STG_AUDIT_EVENTS (
  run_id VARCHAR,
  event_id VARCHAR,
  received_at VARCHAR,
  source VARCHAR,
  incident_types VARCHAR,
  incident_count VARCHAR,
  is_compound VARCHAR,
  outcome VARCHAR,
  writes_confirmed VARCHAR,
  writes_rejected VARCHAR,
  writes_unknown VARCHAR,
  reads VARCHAR,
  blocked_by_validation VARCHAR,
  escalated VARCHAR,
  action_kinds VARCHAR,
  extractor VARCHAR,
  duration_ms VARCHAR,
  summary VARCHAR,
  snapshot_id VARCHAR
);

CREATE TABLE IF NOT EXISTS AUDIT_INCIDENTS (
  run_id VARCHAR,
  event_id VARCHAR,
  incident_id VARCHAR,
  type VARCHAR,
  confirmed BOOLEAN,
  agent VARCHAR,
  decision VARCHAR,
  policy_refs VARIANT,
  plant_id VARCHAR,
  part_id VARCHAR,
  supplier_id VARCHAR,
  shipment_id VARCHAR,
  lot_id VARCHAR,
  impact_window VARCHAR,
  date_phrases VARIANT,
  affected_orders INTEGER,
  vehicles_traced INTEGER,
  path_edge_count INTEGER,
  path_edge_types VARIANT,
  path_ref VARCHAR,
  unresolved VARCHAR,
  reason VARCHAR,
  loaded_at TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  CONSTRAINT pk_audit_incidents PRIMARY KEY (run_id, event_id, incident_id)
);
CREATE TRANSIENT TABLE IF NOT EXISTS STG_AUDIT_INCIDENTS (
  run_id VARCHAR,
  event_id VARCHAR,
  incident_id VARCHAR,
  type VARCHAR,
  confirmed VARCHAR,
  agent VARCHAR,
  decision VARCHAR,
  policy_refs VARCHAR,
  plant_id VARCHAR,
  part_id VARCHAR,
  supplier_id VARCHAR,
  shipment_id VARCHAR,
  lot_id VARCHAR,
  impact_window VARCHAR,
  date_phrases VARCHAR,
  affected_orders VARCHAR,
  vehicles_traced VARCHAR,
  path_edge_count VARCHAR,
  path_edge_types VARCHAR,
  path_ref VARCHAR,
  unresolved VARCHAR,
  reason VARCHAR
);

CREATE TABLE IF NOT EXISTS AUDIT_ACTIONS (
  run_id VARCHAR,
  event_id VARCHAR,
  action_seq INTEGER,
  client_seq INTEGER,
  tool VARCHAR,
  kind VARCHAR,
  status VARCHAR,
  http_status INTEGER,
  server_logged BOOLEAN,
  server_ok BOOLEAN,
  failure_class VARCHAR,
  error VARCHAR,
  duration_ms FLOAT,
  agent VARCHAR,
  policy_rule VARCHAR,
  incident_ids VARIANT,
  purpose VARCHAR,
  args_sanitized VARIANT,
  loaded_at TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  CONSTRAINT pk_audit_actions PRIMARY KEY (run_id, event_id, action_seq)
);
CREATE TRANSIENT TABLE IF NOT EXISTS STG_AUDIT_ACTIONS (
  run_id VARCHAR,
  event_id VARCHAR,
  action_seq VARCHAR,
  client_seq VARCHAR,
  tool VARCHAR,
  kind VARCHAR,
  status VARCHAR,
  http_status VARCHAR,
  server_logged VARCHAR,
  server_ok VARCHAR,
  failure_class VARCHAR,
  error VARCHAR,
  duration_ms VARCHAR,
  agent VARCHAR,
  policy_rule VARCHAR,
  incident_ids VARCHAR,
  purpose VARCHAR,
  args_sanitized VARCHAR
);

CREATE OR REPLACE VIEW V_RUN_SUMMARY AS
SELECT e.run_id, MIN(e.snapshot_id) AS snapshot_id, MIN(e.extractor) AS extractor, COUNT(*) AS events,
       SUM(IFF(e.outcome = 'no_action_noise', 1, 0)) AS noise_events,
       SUM(IFF(e.escalated, 1, 0)) AS escalated_events,
       SUM(e.writes_confirmed) AS writes_confirmed, SUM(e.writes_rejected) AS writes_rejected,
       SUM(e.writes_unknown) AS writes_unknown, SUM(e.reads) AS reads, ROUND(SUM(e.duration_ms) / 1000, 2) AS seconds
FROM AUDIT_EVENTS e GROUP BY e.run_id;

CREATE OR REPLACE VIEW V_EVENT_OUTCOMES AS
SELECT e.run_id, e.event_id, e.received_at, e.source, e.incident_types, e.is_compound, e.outcome, e.action_kinds,
       e.writes_confirmed, e.writes_rejected + e.writes_unknown AS writes_failed, e.escalated, e.summary,
       COUNT(i.incident_id) AS incidents, SUM(i.path_edge_count) AS graph_edges_cited
FROM AUDIT_EVENTS e LEFT JOIN AUDIT_INCIDENTS i ON i.run_id = e.run_id AND i.event_id = e.event_id
GROUP BY ALL;

CREATE OR REPLACE VIEW V_FAILED_CALLS AS
SELECT run_id, event_id, action_seq, tool, status, failure_class, http_status, server_logged, server_ok, error, agent,
       policy_rule, incident_ids
FROM AUDIT_ACTIONS WHERE status <> 'confirmed';

CREATE OR REPLACE VIEW V_ESCALATIONS AS
SELECT a.run_id, a.event_id, a.action_seq, e.source, e.incident_types, e.outcome, i.incident_id, i.type, i.unresolved,
       i.reason, e.writes_confirmed AS operational_writes
FROM AUDIT_ACTIONS a
JOIN AUDIT_EVENTS e ON e.run_id = a.run_id AND e.event_id = a.event_id
LEFT JOIN AUDIT_INCIDENTS i ON i.run_id = a.run_id AND i.event_id = a.event_id
     AND (i.decision LIKE 'escalate%' OR i.unresolved IS NOT NULL)
WHERE a.tool = 'escalate';

CREATE OR REPLACE VIEW V_ACTION_POLICY AS
SELECT x.run_id, x.event_id, x.action_seq, x.tool, x.status, x.agent, x.policy_rule, x.purpose,
       x.incident_id, i.type AS incident_type, i.path_ref, x.args_sanitized
FROM (SELECT a.*, f.value::STRING AS incident_id
      FROM AUDIT_ACTIONS a, LATERAL FLATTEN(input => a.incident_ids, outer => TRUE) f
      WHERE a.kind <> 'read') x
LEFT JOIN AUDIT_INCIDENTS i ON i.run_id = x.run_id AND i.event_id = x.event_id AND i.incident_id = x.incident_id;

